 static Boolean FindDisk(KernelDeviceHandle device,out Disk* d){d=null;for(UInt32 i=0;i<_diskCapacity;i++){Disk* x=_disks+i;if(x->Used!=0&&x->DeviceHandle==device.Value){d=x;return true;}}return false;}
